//! Test-only event recorder and process-global installation guard.
//!
//! Behind the `test-support` feature rather than `#[cfg(test)]`, and `pub`
//! rather than `pub(crate)`, because the event bus now lives in this crate
//! while most of the tests that assert on published events are
//! `tinymemory-core`'s. Same shape as [`crate::host::test_support`]: core
//! enables the feature from its dev-dependencies, and nothing enables it in a
//! shipped build.

use super::*;

#[derive(Debug, Default)]
pub struct RecordingSink {
    events: std::sync::Mutex<Vec<MemoryEvent>>,
}

impl RecordingSink {
    #[must_use]
    pub fn install() -> RecordingSinkGuard {
        static TEST_SINK_LOCK: std::sync::Mutex<()> = std::sync::Mutex::new(());
        let lock = TEST_SINK_LOCK
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner());
        let previous = event_sink();
        let sink = Arc::new(Self::default());
        let installed = Arc::clone(&sink) as Arc<dyn MemoryEventSink>;
        set_event_sink(Arc::clone(&installed));
        RecordingSinkGuard {
            sink,
            installed,
            previous,
            _lock: lock,
        }
    }

    pub fn drain(&self) -> Vec<MemoryEvent> {
        std::mem::take(&mut *self.events.lock().expect("recording sink lock"))
    }
}

pub struct RecordingSinkGuard {
    sink: Arc<RecordingSink>,
    installed: Arc<dyn MemoryEventSink>,
    previous: Option<Arc<dyn MemoryEventSink>>,
    _lock: std::sync::MutexGuard<'static, ()>,
}

impl std::ops::Deref for RecordingSinkGuard {
    type Target = RecordingSink;
    fn deref(&self) -> &Self::Target {
        &self.sink
    }
}

impl Drop for RecordingSinkGuard {
    fn drop(&mut self) {
        let still_installed = event_sink()
            .as_ref()
            .is_some_and(|current| Arc::ptr_eq(current, &self.installed));
        if still_installed {
            match self.previous.take() {
                Some(previous) => set_event_sink(previous),
                None => clear_event_sink(),
            }
        }
    }
}

impl MemoryEventSink for RecordingSink {
    fn publish(&self, event: MemoryEvent) {
        self.events.lock().expect("recording sink lock").push(event);
    }
}

//! [`TestHostConfig`] — a concrete, `Default`-able [`MemoryHostConfig`] for
//! tests.
//!
//! `tinymemory_core::Config` is `dyn MemoryHostConfig`, which cannot be
//! `Default::default()`ed. The extracted test suites build a config, tweak two
//! or three fields, and pass `&config` into the code under test — a pattern
//! that needs a real struct. This is that struct.
//!
//! It is behind the `test-support` feature and enabled from
//! `tinymemory-core`'s dev-dependencies, so it never enters a shipped build.
//! It is deliberately *not* a mock: the fields are the real config sections
//! with their real serde defaults, so a test that asserts on default behaviour
//! is asserting on the same values production loads.

use std::path::PathBuf;

use super::cloud_providers::CloudProviderCreds;
use super::config::{ComposioMode, MemoryHostConfig};
use super::local_ai::LocalAiConfig;
use super::scheduler_gate::SchedulerGateConfig;
use super::storage_memory::{MemoryConfig, MemoryTreeConfig};

/// A concrete host config for tests. Fields are public — mutate them directly
/// rather than reaching for a builder.
#[derive(Debug, Clone, Default)]
#[non_exhaustive]
pub struct TestHostConfig {
    /// See [`MemoryHostConfig::workspace_dir`].
    pub workspace_dir: PathBuf,
    /// See [`MemoryHostConfig::config_path`].
    pub config_path: PathBuf,
    /// See [`MemoryHostConfig::memory`].
    pub memory: MemoryConfig,
    /// See [`MemoryHostConfig::session_token`]. `None` is signed-out.
    pub session_token: Option<String>,
    /// See [`MemoryHostConfig::memory_tree`].
    pub memory_tree: MemoryTreeConfig,
    /// See [`MemoryHostConfig::scheduler_gate`].
    pub scheduler_gate: SchedulerGateConfig,
    /// See [`MemoryHostConfig::local_ai`].
    pub local_ai: LocalAiConfig,
    /// See [`MemoryHostConfig::cloud_providers`].
    pub cloud_providers: Vec<CloudProviderCreds>,
    /// See [`MemoryHostConfig::embeddings_provider`].
    pub embeddings_provider: Option<String>,
    /// See [`MemoryHostConfig::memory_provider`].
    pub memory_provider: Option<String>,
    /// See [`MemoryHostConfig::memory_driver`]. `None` selects the host default.
    pub memory_driver: Option<String>,
    /// See [`MemoryHostConfig::api_url`].
    pub api_url: Option<String>,
    /// See [`MemoryHostConfig::default_model`].
    pub default_model: Option<String>,
    /// See [`MemoryHostConfig::default_temperature`].
    pub default_temperature: f64,
    /// See [`MemoryHostConfig::output_language`].
    pub output_language: Option<String>,
    /// See [`MemoryHostConfig::memory_sync_interval_secs`].
    pub memory_sync_interval_secs: Option<u64>,
    /// See [`MemoryHostConfig::onboarding_completed`].
    pub onboarding_completed: bool,
    /// See [`MemoryHostConfig::secrets_encrypt`].
    pub secrets_encrypt: bool,
    /// See [`MemoryHostConfig::composio`].
    pub composio: ComposioMode,
    /// See [`MemoryHostConfig::memory_sources_json`]. Defaults to an empty
    /// array so a test that never touches sources behaves like a fresh install.
    pub memory_sources: Option<serde_json::Value>,
    /// See [`MemoryHostConfig::composio_source_caps_migration_version`].
    pub composio_source_caps_migration_version: u32,
}

#[async_trait::async_trait]
impl MemoryHostConfig for TestHostConfig {
    fn workspace_dir(&self) -> &PathBuf {
        &self.workspace_dir
    }

    fn config_path(&self) -> &PathBuf {
        &self.config_path
    }

    fn memory_tree_content_root(&self) -> PathBuf {
        self.memory_tree
            .content_dir
            .clone()
            .unwrap_or_else(|| self.workspace_dir.join("memory_tree").join("content"))
    }

    fn memory(&self) -> &MemoryConfig {
        &self.memory
    }

    fn memory_tree(&self) -> &MemoryTreeConfig {
        &self.memory_tree
    }

    fn scheduler_gate(&self) -> &SchedulerGateConfig {
        &self.scheduler_gate
    }

    fn local_ai(&self) -> &LocalAiConfig {
        &self.local_ai
    }

    fn cloud_providers(&self) -> &Vec<CloudProviderCreds> {
        &self.cloud_providers
    }

    fn embeddings_provider(&self) -> Option<&str> {
        self.embeddings_provider.as_deref()
    }

    fn memory_provider(&self) -> Option<&str> {
        self.memory_provider.as_deref()
    }

    fn memory_driver(&self) -> Option<&str> {
        self.memory_driver.as_deref()
    }

    fn workload_local_model(&self, workload: &str) -> Option<String> {
        let raw = match workload {
            "memory" => self.memory_provider.as_deref(),
            "embeddings" => self.embeddings_provider.as_deref(),
            _ => None,
        }?;
        let model = raw.trim().strip_prefix("ollama:")?.trim();
        if model.is_empty() {
            None
        } else {
            Some(model.to_string())
        }
    }

    fn as_any(&self) -> &dyn std::any::Any {
        self
    }

    fn to_arc(&self) -> std::sync::Arc<dyn MemoryHostConfig> {
        std::sync::Arc::new(self.clone())
    }

    fn api_url(&self) -> Option<&str> {
        self.api_url.as_deref()
    }

    fn effective_backend_api_url(&self) -> String {
        // No resolution to do: a test config states its backend URL outright,
        // and the host's env/default ladder is not something to reimplement
        // here.
        self.api_url.clone().unwrap_or_default()
    }

    fn session_token(&self) -> Result<Option<String>, String> {
        // `Ok(None)` — "read fine, not signed in" — rather than `Err`, so a
        // test that never sets a token exercises the signed-out path instead of
        // a credential-store failure.
        Ok(self.session_token.clone())
    }

    fn default_model(&self) -> Option<&str> {
        self.default_model.as_deref()
    }

    fn default_temperature(&self) -> f64 {
        self.default_temperature
    }

    fn output_language(&self) -> Option<&str> {
        self.output_language.as_deref()
    }

    fn memory_sync_interval_secs(&self) -> Option<u64> {
        self.memory_sync_interval_secs
    }

    fn onboarding_completed(&self) -> bool {
        self.onboarding_completed
    }

    fn secrets_encrypt(&self) -> bool {
        self.secrets_encrypt
    }

    fn composio(&self) -> ComposioMode {
        self.composio.clone()
    }

    fn memory_sources_json(&self) -> anyhow::Result<serde_json::Value> {
        Ok(self
            .memory_sources
            .clone()
            .unwrap_or_else(|| serde_json::Value::Array(Vec::new())))
    }

    fn set_memory_sources_json(&mut self, value: serde_json::Value) -> anyhow::Result<()> {
        self.memory_sources = Some(value);
        Ok(())
    }

    fn composio_source_caps_migration_version(&self) -> u32 {
        self.composio_source_caps_migration_version
    }

    fn set_composio_source_caps_migration_version(&mut self, version: u32) {
        self.composio_source_caps_migration_version = version;
    }

    fn apply_env_overrides(&mut self) {}

    async fn save(&self) -> anyhow::Result<()> {
        Ok(())
    }
}

//! Tests for the surrounding module.

use super::*;

#[test]
fn llm_default_is_cloud() {
    assert_eq!(LlmBackend::default(), LlmBackend::Cloud);
    assert_eq!(MemoryTreeConfig::default().llm_backend, LlmBackend::Cloud);
}

#[test]
fn llm_round_trip() {
    for v in [LlmBackend::Cloud, LlmBackend::Local] {
        assert_eq!(LlmBackend::parse(v.as_str()).unwrap(), v);
    }
}

#[test]
fn llm_parse_is_case_insensitive() {
    assert_eq!(LlmBackend::parse("CLOUD").unwrap(), LlmBackend::Cloud);
    assert_eq!(LlmBackend::parse(" Local ").unwrap(), LlmBackend::Local);
}

#[test]
fn llm_parse_rejects_unknown() {
    assert!(LlmBackend::parse("hybrid").is_err());
    assert!(LlmBackend::parse("").is_err());
}

#[test]
fn cloud_llm_model_default_is_summarizer_v1() {
    let cfg = MemoryTreeConfig::default();
    assert_eq!(
        cfg.cloud_llm_model.as_deref(),
        Some(DEFAULT_CLOUD_LLM_MODEL)
    );
    assert_eq!(DEFAULT_CLOUD_LLM_MODEL, "summarization-v1");
}

/// #5056: spaCy is opt-in — a fresh install must never provision the
/// spaCy venv / `en_core_web_sm` model, nor spawn the runtime Python
/// server, without an explicit config or env-var opt-in.
#[test]
fn spacy_enabled_defaults_to_false() {
    assert!(!MemoryTreeConfig::default().spacy_enabled);
    assert!(!default_memory_tree_spacy_enabled());
}

#[test]
fn memory_tree_config_default_content_dir_is_none() {
    let cfg = MemoryTreeConfig::default();
    assert!(
        cfg.content_dir.is_none(),
        "default content_dir must be None so workspace default path is used"
    );
}

/// Verify that the env-var override logic correctly maps non-empty strings
/// to `Some(PathBuf)` and empty/blank strings to `None`. We test the
/// logic inline (not via `apply_env_overrides`) to avoid mutating the
/// process environment in a way that could race with parallel tests.
#[test]
fn content_dir_env_override_logic() {
    // Simulate the load.rs overlay logic.
    let apply = |raw: &str| -> Option<PathBuf> {
        let trimmed = raw.trim();
        if trimmed.is_empty() {
            None
        } else {
            Some(PathBuf::from(trimmed))
        }
    };

    assert_eq!(apply("/tmp/foo"), Some(PathBuf::from("/tmp/foo")));
    assert_eq!(apply("  /tmp/foo  "), Some(PathBuf::from("/tmp/foo")));
    assert_eq!(apply(""), None);
    assert_eq!(apply("   "), None);
}

#[test]
fn memory_config_debug_redacts_agentmemory_secret() {
    let cfg = MemoryConfig {
        agentmemory_secret: Some("bearer-secret".into()),
        ..Default::default()
    };
    let debug = format!("{cfg:?}");
    assert!(!debug.contains("bearer-secret"));
    assert!(debug.contains("<redacted>"));
}

#[test]
fn memory_config_deserialization_supplies_operational_defaults() {
    let cfg: MemoryConfig = toml::from_str("").unwrap();
    assert_eq!(cfg.backend, "sqlite");
    assert!(cfg.auto_save);
    assert_eq!(cfg.embedding_provider, "cloud");
    assert_eq!(cfg.embedding_model, "embedding-v1");
    assert_eq!(cfg.embedding_dimensions, 1024);
    assert_eq!(cfg.embedding_rate_limit_per_min, 60);
}

//! Tests for the surrounding module.

#![allow(clippy::expect_used, clippy::panic)]

use super::{credential_header, Auth, HttpClient};

/// The point of the helper. `reqwest` only redacts a header value whose
/// sensitive flag is set, and `RequestBuilder::header` handed a plain
/// string leaves it clear -- which is how an API key ends up rendered in
/// full by anything that formats the request.
#[test]
fn a_credential_header_is_marked_sensitive() {
    let header = credential_header("Token m0-secret").expect("a plain key is a valid header");
    assert!(header.is_sensitive());
}

/// The value still has to be the credential; marking it sensitive must not
/// change what goes on the wire.
#[test]
fn marking_it_sensitive_does_not_change_the_value() {
    let header = credential_header("Token m0-secret").expect("valid");
    assert_eq!(header.as_bytes(), b"Token m0-secret");
}

/// A credential carrying a newline cannot be a header. Rejecting it here
/// names the credential; letting it through defers the failure into `send`,
/// where it reads as a transport fault.
#[test]
fn a_credential_that_cannot_be_a_header_is_refused_by_name() {
    let error = credential_header("key\r\nX-Injected: 1").expect_err("must not be accepted");
    assert!(format!("{error}").contains("credential"), "got: {error}");
}

/// And the refusal must not print the credential it refused.
#[test]
fn the_refusal_does_not_echo_the_credential() {
    let error = credential_header("supersecret\nX-Injected: 1").expect_err("must not be accepted");
    let rendered = format!("{error:?}");
    assert!(!rendered.contains("supersecret"), "leaked: {rendered}");
}

/// Both credential-bearing schemes go through the helper, so both reach
/// the wire redacted. `Auth::Bearer` is covered by `reqwest`'s own
/// `bearer_auth`, which sets the flag itself.
#[test]
fn both_manual_schemes_send_a_sensitive_authorization_value() {
    for auth in [
        Auth::ApiKey("cg-secret".into()),
        Auth::Token("m0-secret".into()),
    ] {
        let client = HttpClient::new("https://example.test", auth).expect("valid endpoint");
        let request = client
            .request(reqwest::Method::GET, "v1/thing")
            .expect("a plain key builds")
            .build()
            .expect("request builds");
        let sensitive = request
            .headers()
            .values()
            .any(reqwest::header::HeaderValue::is_sensitive);
        assert!(sensitive, "no sensitive header on {:?}", request.headers());
    }
}

# Implementation plans

Plans turn an accepted specification into a reviewable sequence of small,
verifiable changes. They explain how to build the behavior; the linked
specification remains the source of truth for what the behavior must be.

Use the same kebab-case stem as the specification. A useful plan includes:

- a link to the accepted specification;
- the goal, non-goals, and assumptions relevant to implementation;
- ordered tasks with exact file paths;
- a failing test before each behavior change;
- the minimal implementation needed to pass that test;
- documentation and public-export updates;
- focused and full verification commands;
- a completion checklist updated as tasks land.

Prefer tasks that can be implemented and reviewed independently. Include short
code snippets when they remove ambiguity, but do not paste entire future files
into the plan.

See [`example-retry-policy.md`](example-retry-policy.md) for a test-first sample.

//! Unit tests for the memory RPC request/response models, covering
//! deserialization compatibility and limit-resolution helpers.

use super::*;
use serde_json::json;

#[test]
fn recall_memories_request_accepts_compatibility_noop_params() {
    let request: RecallMemoriesRequest = serde_json::from_value(json!({
        "namespace": "team",
        "top_k": 7,
        "min_retention": 0.8,
        "as_of": 1700000000.0
    }))
    .expect("compatibility params should deserialize");

    assert_eq!(request.namespace, "team");
    assert_eq!(request.top_k, Some(7));
    assert_eq!(request.min_retention, Some(0.8));
    assert_eq!(request.as_of, Some(1_700_000_000.0));
}

#[test]
fn recall_memories_request_limit_resolution_ignores_compatibility_noop_params() {
    let request: RecallMemoriesRequest = serde_json::from_value(json!({
        "namespace": "team",
        "limit": 3,
        "min_retention": 0.5,
        "as_of": 1700000000.0
    }))
    .expect("request should deserialize");

    assert_eq!(request.resolved_limit(), 3);
}

// ── resolved_limit priorities ─────────────────────────────────

#[test]
fn recall_memories_resolved_limit_prefers_top_k_over_max_chunks_and_limit() {
    let req = RecallMemoriesRequest {
        namespace: "n".into(),
        min_retention: None,
        as_of: None,
        limit: Some(5),
        max_chunks: Some(7),
        top_k: Some(9),
    };
    assert_eq!(req.resolved_limit(), 9);
}

#[test]
fn recall_memories_resolved_limit_falls_back_to_max_chunks_then_limit_then_default() {
    let without_top_k = RecallMemoriesRequest {
        namespace: "n".into(),
        min_retention: None,
        as_of: None,
        limit: Some(5),
        max_chunks: Some(7),
        top_k: None,
    };
    assert_eq!(without_top_k.resolved_limit(), 7);

    let limit_only = RecallMemoriesRequest {
        namespace: "n".into(),
        min_retention: None,
        as_of: None,
        limit: Some(5),
        max_chunks: None,
        top_k: None,
    };
    assert_eq!(limit_only.resolved_limit(), 5);

    let none = RecallMemoriesRequest {
        namespace: "n".into(),
        min_retention: None,
        as_of: None,
        limit: None,
        max_chunks: None,
        top_k: None,
    };
    assert_eq!(none.resolved_limit(), 10);
}

#[test]
fn query_namespace_resolved_limit_prefers_max_chunks_then_limit_then_default() {
    let req = QueryNamespaceRequest {
        namespace: "n".into(),
        query: "q".into(),
        include_references: None,
        document_ids: None,
        limit: Some(3),
        max_chunks: Some(9),
    };
    assert_eq!(req.resolved_limit(), 9);

    let req_limit_only = QueryNamespaceRequest {
        namespace: "n".into(),
        query: "q".into(),
        include_references: None,
        document_ids: None,
        limit: Some(3),
        max_chunks: None,
    };
    assert_eq!(req_limit_only.resolved_limit(), 3);

    let req_none = QueryNamespaceRequest {
        namespace: "n".into(),
        query: "q".into(),
        include_references: None,
        document_ids: None,
        limit: None,
        max_chunks: None,
    };
    assert_eq!(req_none.resolved_limit(), 10);
}

#[test]
fn recall_context_resolved_limit_prefers_max_chunks_then_limit_then_default() {
    let req = RecallContextRequest {
        namespace: "n".into(),
        include_references: None,
        limit: Some(3),
        max_chunks: Some(9),
    };
    assert_eq!(req.resolved_limit(), 9);

    let req_limit_only = RecallContextRequest {
        namespace: "n".into(),
        include_references: None,
        limit: Some(3),
        max_chunks: None,
    };
    assert_eq!(req_limit_only.resolved_limit(), 3);

    let req_none = RecallContextRequest {
        namespace: "n".into(),
        include_references: None,
        limit: None,
        max_chunks: None,
    };
    assert_eq!(req_none.resolved_limit(), 10);
}

// ── deny_unknown_fields enforcement ───────────────────────────

#[test]
fn query_namespace_request_rejects_unknown_fields() {
    let err = serde_json::from_value::<QueryNamespaceRequest>(json!({
        "namespace": "n",
        "query": "q",
        "bogus": 1
    }))
    .unwrap_err();
    assert!(err.to_string().contains("bogus"));
}

#[test]
fn recall_context_request_rejects_unknown_fields() {
    let err = serde_json::from_value::<RecallContextRequest>(json!({
        "namespace": "n",
        "bogus": true
    }))
    .unwrap_err();
    assert!(err.to_string().contains("bogus"));
}

#[test]
fn empty_request_rejects_any_field() {
    let err = serde_json::from_value::<EmptyRequest>(json!({"x": 1})).unwrap_err();
    assert!(err.to_string().contains("x"));
    serde_json::from_value::<EmptyRequest>(json!({})).unwrap();
}

// ── MemoryInitRequest tolerates backwards-compatible jwt_token ────

#[test]
fn memory_init_request_jwt_token_is_optional_and_ignored() {
    let without: MemoryInitRequest = serde_json::from_value(json!({})).unwrap();
    assert_eq!(without.jwt_token, None);
    let with: MemoryInitRequest = serde_json::from_value(json!({"jwt_token": "abc"})).unwrap();
    assert_eq!(with.jwt_token.as_deref(), Some("abc"));
}

// ── ApiError / ApiMeta / ApiEnvelope round-trip ──────────────

#[test]
fn api_error_round_trips_with_optional_details() {
    let err = ApiError {
        code: "E".into(),
        message: "boom".into(),
        details: Some(json!({"why": "reason"})),
    };
    let s = serde_json::to_string(&err).unwrap();
    let back: ApiError = serde_json::from_str(&s).unwrap();
    assert_eq!(back.code, "E");
    assert_eq!(back.message, "boom");
    assert!(back.details.is_some());
}

#[test]
fn api_error_without_details_omits_field_when_serialized() {
    let err = ApiError {
        code: "E".into(),
        message: "boom".into(),
        details: None,
    };
    let s = serde_json::to_string(&err).unwrap();
    assert!(!s.contains("details"), "got: {s}");
}

#[test]
fn api_envelope_round_trip_preserves_data_and_meta() {
    let env = ApiEnvelope::<u32> {
        data: Some(42),
        error: None,
        meta: ApiMeta {
            request_id: "r1".into(),
            latency_seconds: Some(0.5),
            cached: Some(false),
            counts: None,
            pagination: Some(PaginationMeta {
                limit: 10,
                offset: 0,
                count: 1,
            }),
        },
    };
    let s = serde_json::to_string(&env).unwrap();
    let back: ApiEnvelope<u32> = serde_json::from_str(&s).unwrap();
    assert_eq!(back.data, Some(42));
    assert!(back.error.is_none());
    assert_eq!(back.meta.pagination.unwrap().count, 1);
}

#[test]
fn default_memory_relative_dir_is_memory() {
    // Empty string == the memory root itself (`<workspace>/memory`).
    assert_eq!(crate::rpc_models::default_memory_relative_dir(), "");
}

//! Tests for fail-closed defaults on [`super::Memory`].

use std::sync::atomic::{AtomicUsize, Ordering};

use async_trait::async_trait;

use super::Memory;
use crate::types::{MemoryCategory, MemoryEntry, MemoryTaint, NamespaceSummary, RecallOpts};

#[derive(Default)]
struct MinimalMemory {
    stores: AtomicUsize,
}

#[async_trait]
impl Memory for MinimalMemory {
    fn name(&self) -> &str {
        "minimal"
    }

    async fn store(
        &self,
        _: &str,
        _: &str,
        _: &str,
        _: MemoryCategory,
        _: Option<&str>,
    ) -> anyhow::Result<()> {
        self.stores.fetch_add(1, Ordering::Relaxed);
        Ok(())
    }

    async fn recall(
        &self,
        _: &str,
        _: usize,
        _: RecallOpts<'_>,
    ) -> anyhow::Result<Vec<MemoryEntry>> {
        Ok(Vec::new())
    }
    async fn get(&self, _: &str, _: &str) -> anyhow::Result<Option<MemoryEntry>> {
        Ok(None)
    }
    async fn list(
        &self,
        _: Option<&str>,
        _: Option<&MemoryCategory>,
        _: Option<&str>,
    ) -> anyhow::Result<Vec<MemoryEntry>> {
        Ok(Vec::new())
    }
    async fn forget(&self, _: &str, _: &str) -> anyhow::Result<bool> {
        Ok(false)
    }
